<?php
$letterheadUrl = trim((string) ($letterheadUrl ?? ''));
$letterheadMarkup = $letterheadUrl !== '' ? '<img class="print-letterhead" src="' . htmlspecialchars($letterheadUrl, ENT_QUOTES, 'UTF-8') . '" alt="School letterhead">' : '';
ob_start(function ($output) use ($letterheadMarkup) {
    $output = str_replace('@page{size:A4 landscape;margin:12mm}', '@page{size:A4 portrait;margin:10mm}', $output);
    $output = str_replace('.annex-table{font-size:12px}', '.annex-table{font-size:10px}.annex-table th,.annex-table td{padding:5px}.cell-line{margin-bottom:5px}', $output);
    $output = str_replace('.muted{color:#666;font-size:12px}', '.muted{display:none}', $output);
    $output = str_replace('.report-head p{margin:6px 0;color:#555}', '.report-head p{margin:6px 0;color:#555}.report-head p:first-of-type{display:none}', $output);
    $output = str_replace(
        'This table reflects the aggregate personnel data required under Item 6 of the mandatory documentary requirements.',
        'This table reflects the aggregate data of the administrative, teaching, and non-teaching personnel as required under Item 6 of the mandatory documentary requirements.',
        $output
    );
    $output = str_replace('</style>', '.print-letterhead{display:block;width:100%;max-width:none;max-height:220px;object-fit:contain;object-position:top;margin:0 0 14px}</style>', $output);
    if ($letterheadMarkup !== '') {
        $output = str_replace('<main class="report">', '<main class="report">' . $letterheadMarkup, $output);
    }
    return $output;
});
$esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};
$records=is_array($personnel)?$personnel:array();
$by=function($callback)use($records){return array_values(array_filter($records,$callback));};
$countValue=function($rows,$field,$value){return count(array_filter($rows,function($row)use($field,$value){return trim((string)($row->$field??''))===$value;}));};
$line=function($label,$value){return $label.': '.number_format((int)$value);};
$unique=function($rows,$field){$values=array();foreach($rows as $row){$value=trim((string)($row->$field??''));if($value!==''&&!in_array($value,$values,true))$values[]=$value;}return $values?implode(', ',$values):'—';};
$benefits=function($rows){$items=array();foreach($rows as $row){foreach(explode('|',(string)($row->benefits??''))as$item){$item=trim($item);if($item!==''&&!in_array($item,$items,true))$items[]=$item;}}return $items?implode(', ',$items):'—';};
$avgDays=function($rows){$days=array();foreach($rows as $row){if((int)($row->working_days_per_week??0)>0)$days[]=(int)$row->working_days_per_week;}return $days?number_format(array_sum($days)/count($days),1):'—';};
$admin=$by(function($r){return ($r->personnel_type??'')==='Administrative';});
$full=$by(function($r){return ($r->personnel_type??'')==='Teaching'&&($r->employment_status??'')==='Full-time';});
$part=$by(function($r){return ($r->personnel_type??'')==='Teaching'&&($r->employment_status??'')==='Part-time';});
$non=$by(function($r){return ($r->personnel_type??'')==='Non-Teaching';});
$teacherQualification=function($rows)use($countValue){return array($countValue($rows,'qualification_classification',"Bachelor's Degree"),$countValue($rows,'qualification_classification',"Master's Degree"),$countValue($rows,'qualification_classification','Specialist / Industry Expert'),count(array_filter($rows,function($r){return !empty($r->licensed);})));};
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Annex D — Personnel Profile</title><link href="<?= base_url();?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?= base_url();?>assets/css/icons.min.css" rel="stylesheet"><style>body{background:#eef2f7;color:#202124}.report{max-width:1120px;margin:30px auto;padding:38px;background:#fff;box-shadow:0 5px 25px rgba(0,0,0,.12)}.toolbar{max-width:1120px;margin:22px auto 0;display:flex;justify-content:space-between}.report-head{text-align:center;margin-bottom:24px}.report-head h1{font-size:18px;font-weight:800;margin:0}.report-head h2{font-size:16px;font-weight:800;margin:10px 0}.report-head p{margin:6px 0;color:#555}.annex-table{width:100%;border-collapse:collapse;font-size:13px}.annex-table th,.annex-table td{border:1px solid #60656b;padding:10px;vertical-align:top}.annex-table th{text-align:center;font-size:13px;line-height:1.25}.category{width:18%;font-weight:800;font-size:14px}.qual{width:22%}.assignment{width:25%}.days{width:14%;text-align:center}.salary{width:21%}.cell-line{margin:0 0 9px;line-height:1.28}.muted{color:#666;font-size:12px}@media print{body{background:#fff}.toolbar{display:none}.report{box-shadow:none;margin:0;max-width:none;padding:0}.annex-table{font-size:12px}@page{size:A4 landscape;margin:12mm}}@media(max-width:700px){.report{margin:0;padding:18px;overflow:auto}.annex-table{min-width:850px}}</style></head><body><div class="toolbar"><a class="btn btn-light" href="<?= base_url();?>Page/school_personnel">← Back to Personnel</a><button class="btn btn-primary" onclick="window.print()"><i class="mdi mdi-printer"></i> Print Report</button></div><main class="report"><header class="report-head"><h1>ANNEX D:</h1><h2>PERSONNEL PROFILE: ADMINISTRATIVE, TEACHING, AND NON-TEACHING STAFF</h2><p><strong><?= $esc($schoolName); ?></strong></p><p>This table reflects the aggregate personnel data required under Item 6 of the mandatory documentary requirements.</p></header><table class="annex-table"><thead><tr><th>Personnel Category and Employment Status</th><th>Qualifications / Eligibilities<br><em>(Degrees / PRC License / Major)</em></th><th>Teaching Load / Work Assignment</th><th>Average Working Days / Week</th><th>Salary Range and Benefits</th></tr></thead><tbody><tr><td class="category">Administrative Personnel<div class="cell-line mt-4">Total: <?= count($admin); ?></div></td><td class="qual"><div class="cell-line"><?= $line('Civil Service',$countValue($admin,'qualification_classification','Civil Service Eligible')); ?></div><div class="cell-line"><?= $line('Others',$countValue($admin,'qualification_classification','Other Qualification')); ?></div></td><td class="assignment"><?php foreach(array('Top Level/Executive Management','Principal/Assistant Principal','Administrative Officer','Registrar/Records Officer','HR Officer/Secretary','Finance Officer/Accountant','Coordinator')as$item):?><div class="cell-line"><?= $line($item,$countValue($admin,'work_assignment',$item)); ?></div><?php endforeach;?></td><td class="days"><?= $avgDays($admin); ?></td><td class="salary"><div class="cell-line"><strong>Salary Range:</strong><br><?= $esc($unique($admin,'salary_range')); ?></div><div class="cell-line"><strong>Benefits:</strong><br><?= $esc($benefits($admin)); ?></div></td></tr><?php foreach(array(array('Full-Time Teachers',$full),array('Part-Time Teachers',$part))as$teacherRow):?><?php $q=$teacherQualification($teacherRow[1]);?><tr><td class="category"><?= $teacherRow[0];?><div class="cell-line mt-4">Total: <?= count($teacherRow[1]); ?></div></td><td class="qual"><div class="cell-line"><?= $line("Bachelor's Degree",$q[0]); ?></div><div class="cell-line"><?= $line("Master's Degree",$q[1]); ?></div><div class="cell-line"><?= $line('Specialists / Industry Experts',$q[2]); ?></div><div class="cell-line"><?= $line('LET Passers',$q[3]); ?></div></td><td class="assignment"><div class="cell-line"><?= $line('Core',$countValue($teacherRow[1],'work_assignment','Core')); ?></div><div class="cell-line"><?= $line('Academic Electives',$countValue($teacherRow[1],'work_assignment','Academic Electives')); ?></div><div class="cell-line"><?= $line('TechPro Electives',$countValue($teacherRow[1],'work_assignment','TechPro Electives')); ?></div></td><td class="days"><?= $avgDays($teacherRow[1]); ?></td><td class="salary"><div class="cell-line"><strong>Salary Range:</strong><br><?= $esc($unique($teacherRow[1],'salary_range')); ?></div><div class="cell-line"><strong>Benefits:</strong><br><?= $esc($benefits($teacherRow[1])); ?></div></td></tr><?php endforeach;?><tr><td class="category">Non-Teaching Personnel<div class="cell-line mt-4">Total: <?= count($non); ?></div></td><td class="qual"><div class="cell-line"><?= $line('Professional',$countValue($non,'qualification_classification','Professional')); ?></div><div class="cell-line"><?= $line('Technical',$countValue($non,'qualification_classification','Technical')); ?></div><div class="cell-line"><?= $line('Others',$countValue($non,'qualification_classification','Other')); ?></div></td><td class="assignment"><?php foreach(array('Administrative Staff','Finance and Accounting Staff','Guidance Counselor','Library Staff','IT / Technical Support','Maintenance / Janitorial / Security / Canteen Staff')as$item):?><div class="cell-line"><?= $line($item,$countValue($non,'work_assignment',$item)); ?></div><?php endforeach;?></td><td class="days"><?= $avgDays($non); ?></td><td class="salary"><div class="cell-line"><strong>Salary Range:</strong><br><?= $esc($unique($non,'salary_range')); ?></div><div class="cell-line"><strong>Benefits:</strong><br><?= $esc($benefits($non)); ?></div></td></tr></tbody></table><p class="muted mt-3 mb-0">Generated on <?= date('F j, Y'); ?> from this school’s personnel records.</p></main></body></html>
